def test_multiple_different_root_paths_do_not_accumulate():
        app = FastAPI()

        @app.get("/")
        def read_root():  # pragma: no cover
            return {"ok": True}

        for prefix in ["/path-a", "/path-b", "/path-c"]:
            c = TestClient(app, root_path=prefix)
            c.get("/openapi.json")

